const app=document.querySelector('#app');
const icons={home:'⌂',explore:'⌕',booking:'▣',help:'♡',pin:'⌖',arrow:'↗',clock:'◷'};
const api=async(path,opts={})=>{const prefix=path.startsWith('/operations/')?'/api/v1':'/api/v1/public';const r=await fetch(prefix+path,{...opts,headers:{'content-type':'application/json',...(opts.headers||{})}});const data=await r.json();if(!r.ok)throw new Error(data.error||'Something went wrong. Please try again.');return data.data;};
let sites=[],operationsSites=[],opsAuth=null,opsLoginConfigured=false,apifyStatus=null,selected=null,view='home',search='',opsSearch='',filter='All',city='All',here=null,locating=false,locationMessage='',mapOpen=true,mapInstance=null,mapLib=null,mapEl=null,markers=new Map(),mapFitKey='',listLimit=20,features={nearbyDiscovery:true,mapView:true,voiceAssistance:false},opsFeatures=null,recorder=null,voiceBusy=false,gateSite=null,scanning=false,scanStream=null,scanLoop=0,gateResult='',justLocated=false,justBooked=false,justScanned=false,toastTimer;
const booking=()=>{try{return JSON.parse(localStorage.getItem('visarjanops-booking'));}catch{return null;}};
const saveBooking=b=>localStorage.setItem('visarjanops-booking',JSON.stringify(b));
function toast(message){let n=document.querySelector('.toast');if(!n){n=document.createElement('div');n.className='toast';document.body.append(n)}n.textContent=message;n.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.classList.remove('show'),3200)}
const badge=s=>`<span class="status ${s==='Available'||s==='Open'?'good':s==='Busy'?'busy':s==='Near capacity'?'warning':'paused'}"><i></i>${escapeHtml(s)}</span>`;
const STAFF_STATUSES=['Open','Busy','Near capacity','Closed'];
// Visitor coordinates (`here`) live only in memory; distances are computed in the browser and never sent to the server.
const toRad=d=>d*Math.PI/180;
function distanceKm(a,b){const dLat=toRad(b.lat-a.lat),dLng=toRad(b.lng-a.lng),x=Math.sin(dLat/2)**2+Math.cos(toRad(a.lat))*Math.cos(toRad(b.lat))*Math.sin(dLng/2)**2;return 2*6371*Math.asin(Math.sqrt(x));}
const hasCoords=s=>Number.isFinite(s?.coordinates?.lat)&&Number.isFinite(s?.coordinates?.lng);
const distanceTo=s=>here&&hasCoords(s)?distanceKm(here,s.coordinates):null;
const formatDistance=km=>km<0.1?'Under 100 m':km<1?`${Math.round(km*20)*50} m`:`${km<10?km.toFixed(1):Math.round(km)} km`;
const distanceText=km=>here?.kind==='area'&&km<0.5?'In this area':`${formatDistance(km)} away`;
const sortedSites=list=>here?[...list].sort((a,b)=>(distanceTo(a)??Infinity)-(distanceTo(b)??Infinity)):list;
const freshnessChip=s=>{const f=s.statusInfo?.freshness||'unavailable';return `<span class="fresh fresh-${f}" title="${escapeHtml(s.statusInfo?.label||'Status unavailable')}">${{live:'Live',delayed:'Delayed',demo:'Simulated',unavailable:'No status'}[f]||'No status'}</span>`};
const statusRow=s=>{const i=s.statusInfo;if(!i||i.freshness==='unavailable'||!i.status)return `<div class="site-status">${freshnessChip(s)}<span class="wait">No current status</span></div>`;return `<div class="site-status">${freshnessChip(s)}${badge(i.status)}${i.wait?`<span class="wait">${icons.clock} ${escapeHtml(i.wait)}</span>`:''}</div>`};
const directionsUrl=s=>{const c=s.coordinates;if(!c||c.kind==='synthetic')return null;if(c.kind==='official-link'&&s.sourceLink)return s.sourceLink;return `https://www.google.com/maps/dir/?api=1&destination=${c.lat},${c.lng}`};
const placeNote=s=>s.coordinates?.kind==='synthetic'?'Sample location · not a real facility':s.provenance?.kind==='official-source'?`${s.provenance.label} · ${s.provenance.festival} ${s.provenance.festivalYear} (past season) · not yet verified`:'';
const bookable=s=>s.provenance?.kind==='demo';
const crowdText=s=>s.crowd?`~${s.crowd.onSite} on site · ${s.crowd.expected} expected`:'';
const card=s=>{const km=distanceTo(s),dir=directionsUrl(s);return `<article class="site-card"><div class="site-art art-${escapeHtml(s.id)}"><div class="art-orbit"></div><span class="art-icon">${s.icon||'◉'}</span><span class="art-caption">${s.id==='lakeview'?'A calm place to gather':s.id==='green'?'Make room for what matters':escapeHtml(s.city||'Community immersion site')}</span>${km!=null?`<span class="distance">${distanceText(km)}</span>`:''}</div><div class="site-body">${statusRow(s)}<h3>${escapeHtml(s.name)}</h3><p class="muted">${icons.pin} ${escapeHtml(s.area)}</p><p class="place-note">${escapeHtml(placeNote(s))}</p><div class="facility-row">${(s.facilities||[]).slice(0,3).map(f=>`<span class="facility">${escapeHtml(f)}</span>`).join('')}</div><div class="card-actions"><button class="text-btn" data-site="${escapeHtml(s.id)}">View site <span>→</span></button>${bookable(s)?`<button class="text-btn" data-book="${escapeHtml(s.id)}">Book arrival <span>→</span></button>`:''}${dir?`<a class="text-btn" href="${dir}" target="_blank" rel="noopener noreferrer">Directions <span>↗</span></a>`:''}</div></div></article>`};
function header(){return `<header class="topbar"><a class="brand" href="#home" aria-label="VisarjanOps home"><span class="brand-mark"><img src="/assets/ganesh-logo.jpg" alt="" aria-hidden="true"></span><span>visarjan<span class="brand-light">ops</span><small>THOUGHTFULLY ORGANISED</small></span></a><nav class="desktop-nav"><a href="#explore">Find a site</a><a href="#booking">My booking</a><a href="#help">Get help</a><a href="${opsAuth?'#operations':'#ops-login'}">${opsAuth?'Operations':'Staff sign in'}</a></nav><div class="top-actions"><a class="staff-mobile-link" aria-label="${opsAuth?'Operations dashboard':'Staff sign in'}" href="${opsAuth?'#operations':'#ops-login'}">${opsAuth?'Ops':'Staff'}</a><button class="language" aria-label="Language">EN⌄</button><button class="profile" aria-label="Profile">◉</button></div></header>`}
function footer(){return `<nav class="mobile-nav"><a href="#home" class="${view==='home'?'active':''}"><span>${icons.home}</span>Home</a><a href="#explore" class="${view==='explore'?'active':''}"><span>${icons.explore}</span>Explore</a><a href="#booking" class="${view==='booking'?'active':''}"><span>${icons.booking}</span>My booking</a><a href="#help" class="${view==='help'?'active':''}"><span>${icons.help}</span>Help</a></nav><footer><div class="foot-brand">VisarjanOps <span>· MCGM SOURCE DATA</span></div><p>Thoughtful planning for a meaningful celebration.</p><p class="disclaimer">Site list extracted from MCGM's published Ganeshotsav 2025 list (past season) and pending operator review. Status appears only when site staff post it, with the time it was posted.</p></footer>`}
function home(){return `${header()}<main><section class="hero river-hero"><canvas class="river-canvas" aria-hidden="true"></canvas><div class="hero-copy"><div class="eyebrow"><span class="sun">✳</span> A MORE THOUGHTFUL VISARJAN</div><h1>Celebrate Ganeshotsav.<br><span>Experience a smoother Visarjan.</span></h1><p>Find official artificial immersion ponds near you, see status posted by site staff and get assistance, all in one thoughtful place.</p><div class="hero-actions"><a class="primary" href="#explore">Find sites near me <span>→</span></a><a class="secondary" href="${opsAuth?'#operations':'#ops-login'}">Manage Operations</a></div><div class="trustline"><span>✳</span> Site discovery <b>·</b> Time-slot booking <b>·</b> Devotee assistance</div></div>${journeyCarousel()}</section><div class="demo-banner"><span class="demo-dot"></span> MUMBAI · MCGM LIST <span class="banner-sep">·</span> Sites from MCGM's published Ganeshotsav 2025 list (past season, pending review). Status shows only when site staff report it.</div><section class="quick-grid"><a href="#explore" class="quick-card"><span class="quick-icon orange">⌕</span><span><b>Find a site</b><small>Explore nearby locations</small></span><span class="quick-arrow">↗</span></a><a href="#booking" class="quick-card"><span class="quick-icon navy">▣</span><span><b>My booking</b><small>Your pass and visit status</small></span><span class="quick-arrow">↗</span></a><a href="#help" class="quick-card"><span class="quick-icon green">♡</span><span><b>Request help</b><small>We're here if you need us</small></span><span class="quick-arrow">↗</span></a><a href="#waste" class="quick-card"><span class="quick-icon gold">♧</span><span><b>Waste guidance</b><small>Leave the site cared for</small></span><span class="quick-arrow">↗</span></a></section><section class="section"><div class="section-heading"><div><div class="eyebrow">A GOOD PLACE TO BEGIN</div><h2>Nearby immersion sites</h2><p class="muted">Compare availability and facilities at example locations.</p></div><a class="view-all" href="#explore">View all sites <span>→</span></a></div><div class="site-grid">${sortedSites(sites).slice(0,3).map(card).join('')}</div></section><section class="how-section"><div class="section-heading"><div><div class="eyebrow">A LITTLE MORE EASE, STEP BY STEP</div><h2>How VisarjanOps works</h2></div></div><div class="how-grid"><article><span>01</span><h3>Find your site</h3><p>Compare location, facilities and the clearly labeled site status.</p></article><article><span>02</span><h3>Check the latest status</h3><p>Site staff post live updates. If nobody has reported recently, we say so.</p></article><article><span>03</span><h3>Celebrate with care</h3><p>Keep your booking reference handy and follow site waste guidance.</p></article></div></section><section class="care-strip"><div class="care-icon">✳</div><div><span class="eyebrow">A LITTLE CARE GOES A LONG WAY</span><h2>Celebrate with care.</h2><p>Choose an authorised immersion location, follow on-site guidance, and sort offerings thoughtfully.</p></div><a href="#waste" class="secondary">Simple waste guidance <span>→</span></a></section></main>${footer()}`}
// Area picker centres come from the listed sites' own published coordinates (averaged per area), never invented.
function areaOptions(){const groups=new Map();for(const s of sites){if(!hasCoords(s))continue;const name=s.area;if(!name||name===s.city)continue;const g=groups.get(name)||{area:name,city:s.city,lat:0,lng:0,n:0};g.lat+=s.coordinates.lat;g.lng+=s.coordinates.lng;g.n++;groups.set(name,g)}return [...groups.values()].map(g=>({id:g.area,area:g.area,city:g.city,lat:g.lat/g.n,lng:g.lng/g.n,n:g.n})).sort((a,b)=>(a.city||'').localeCompare(b.city||'')||a.area.localeCompare(b.area));}
function exploreList(){return sortedSites(sites.filter(s=>(!search||`${s.name} ${s.area} ${s.city||''} ${s.address||''}`.toLowerCase().includes(search.toLowerCase()))&&(city==='All'||s.city===city)&&(filter==='All'||s.statusInfo?.status===filter)));}
function siteRow(s,i=0){const km=distanceTo(s);return `<li class="site-row-item" style="--i:${Math.min(i,12)}"><button class="site-row" data-focus="${escapeHtml(s.id)}"><span class="row-main"><b>${escapeHtml(s.name)}</b><small>${escapeHtml(s.address||s.area)}</small></span><span class="row-meta">${km!=null?`<span class="row-distance">${distanceText(km)}</span>`:''}${freshnessChip(s)}${s.statusInfo?.status?badge(s.statusInfo.status):''}${s.crowd?`<span class="crowd-chip" title="${escapeHtml(s.crowd.source)}">${crowdText(s)}</span>`:''}</span></button><a class="row-link" href="#site/${encodeURIComponent(s.id)}" aria-label="Details for ${escapeHtml(s.name)}">Details →</a></li>`}
function explore(){const list=exploreList(),located=list.filter(hasCoords),pending=list.filter(s=>!hasCoords(s));const cities=['All',...new Set(sites.map(s=>s.city).filter(Boolean))];const sortNote=here?`Nearest first, by straight-line distance from ${here.kind==='device'?'your location':escapeHtml(here.label)}.`:'Share your location or choose an area to see the nearest sites first.';const nearest=here&&located.length?distanceTo(located[0]):null;const farNote=nearest!=null&&nearest>50?`<p class="far-note">The closest listed site is ${formatDistance(nearest)} away. Sites currently come from MCGM’s Mumbai list only.</p>`:'';const rows=located.slice(0,listLimit).map(siteRow).join('');const more=located.length>listLimit?`<button class="secondary full" id="list-more">Show ${Math.min(20,located.length-listLimit)} more</button>`:'';const pendingHtml=pending.length?`<details class="pending-list"><summary>${pending.length} ${pending.length===1?'site has':'sites have'} no readable location yet</summary><ul>${pending.slice(0,120).map(s=>`<li><a href="#site/${encodeURIComponent(s.id)}">${escapeHtml(s.name)}</a></li>`).join('')}</ul></details>`:'';
return `${header()}<main class="page explore-page"><section class="locate-panel"><div class="eyebrow">NEAR YOU</div><h1 class="page-title">Find immersion sites near you.</h1><p class="page-intro">Share your location once, or choose an area, to see the nearest artificial ponds on the map.</p><div class="locate-actions">${features.nearbyDiscovery?`<button class="primary" id="use-location" ${locating?'disabled':''}>${locating?'Finding your location…':`${icons.pin} Use my location`}</button><span class="or-divider">or</span>`:''}${features.voiceAssistance?`<button class="secondary voice-btn ${recorder?'recording':''}" id="voice-search" aria-pressed="${Boolean(recorder)}" ${voiceBusy?'disabled':''}>${recorder?'■ Stop and search':voiceBusy?'Understanding…':'🎙 Ask by voice'}</button>`:''}${features.nearbyDiscovery?'':'<span hidden>'}<label class="area-picker"><span>Choose an area</span><select id="area"><option value="">Select a neighbourhood</option>${areaOptions().map(a=>`<option value="${escapeHtml(a.id)}" ${here?.kind==='area'&&here.siteId===a.id?'selected':''}>${escapeHtml(a.area)} (${a.n})</option>`).join('')}</select></label>${features.nearbyDiscovery?'':'</span>'}${here?'<button class="secondary" id="clear-location">Clear location</button>':''}</div><p class="locate-status" role="status" aria-live="polite">${escapeHtml(locationMessage)}</p><p class="privacy-note">We ask for your location only when you tap the button. It stays in this browser and is never sent to our server or saved.${features.voiceAssistance?' Voice search sends your recording to Sarvam AI to understand it; we don’t store it.':''}</p></section>
<div class="explore-toolbar"><div class="searchbar"><span>⌕</span><input id="search" aria-label="Search sites" placeholder="Search a site, road or area" value="${escapeHtml(search)}"></div><div class="filter-row status-filters" role="group" aria-label="Reported status">${['All',...STAFF_STATUSES].map(f=>`<button class="filter ${filter===f?'on':''}" data-filter="${f}" aria-pressed="${filter===f}">${f==='All'?'Any status':f}</button>`).join('')}</div>${cities.length>2?`<div class="filter-row" role="group" aria-label="City">${cities.map(c=>`<button class="filter ${city===c?'on':''}" data-city="${escapeHtml(c)}" aria-pressed="${city===c}">${c==='All'?'All cities':escapeHtml(c)}</button>`).join('')}</div>`:''}</div>${farNote}
<div class="explore-split ${mapOpen&&features.mapView?'':'list-only'}">${mapOpen&&features.mapView?`<div class="map-pane"><div id="site-map-slot" class="map-slot"></div><p class="map-note">Map: OpenFreeMap · © OpenStreetMap contributors. Pins use locations from MCGM’s published map links. <span class="legend"><i class="lg live"></i>Live <i class="lg delayed"></i>Delayed <i class="lg none"></i>No status</span></p></div>`:''}<aside class="list-pane" aria-label="Sites list"><div class="list-head"><span><b>${located.length}</b> on the map${pending.length?` · ${pending.length} without location`:''}</span>${features.mapView?`<button class="text-toggle" id="map-toggle" aria-pressed="${!mapOpen}">${mapOpen?'List only':'Show map'}</button>`:''}</div><p class="list-note">${sortNote}</p>${located.length?`<ol class="site-rows ${justLocated?'reveal':''}">${rows}</ol>${more}`:`<div class="empty small"><h3>No sites match</h3><p>Try another search or status.</p></div>`}${pendingHtml}</aside></div>
<p class="demo-note">Sites are extracted automatically from MCGM’s published Ganeshotsav 2025 list (past season) and are pending operator review. Status appears only when site staff post an update.</p></main>${footer()}`}
function siteDetail(s){return `${header()}<main class="page detail-page"><a class="back" href="#explore">← All sites</a><div class="detail-layout"><div><div class="detail-art art-${escapeHtml(s.id)}"><span class="art-icon">${s.icon||'◉'}</span>${distanceTo(s)!=null?`<span class="distance">${distanceText(distanceTo(s))}</span>`:''}</div><div class="detail-info">${statusRow(s)}${s.crowd?`<p class="crowd-line"><b>${crowdText(s)}</b> · estimate from gate check-ins and bookings${s.crowd.lastScanAt?`, last scan ${escapeHtml(new Date(s.crowd.lastScanAt).toLocaleTimeString())}`:''}</p>`:''}${s.statusInfo?.observedAt?`<p class="status-source">Status source: ${escapeHtml(s.statusInfo.source)} · ${escapeHtml(new Date(s.statusInfo.observedAt).toLocaleString())}</p>`:''}<h1>${escapeHtml(s.name)}</h1>${s.address?`<p class="muted">⌖ ${escapeHtml(s.address)}</p>`:`<p class="muted">⌖ ${escapeHtml(s.area)}</p>`}<p class="place-note">${escapeHtml(placeNote(s))}</p>${s.description?`<p>${escapeHtml(s.description)}</p>`:''}${s.facilities?.length?`<h3>At this site</h3><div class="facility-grid">${s.facilities.map(f=>`<div>✓ <span>${escapeHtml(f)}</span></div>`).join('')}</div>`:''}${sourcePanel(s)}<h3>Arrival information</h3><p class="muted">${s.hours?`${escapeHtml(s.hours)} · `:''}Follow on-site volunteer and police directions.</p>${directionsUrl(s)?`<a class="secondary directions-link" href="${escapeHtml(directionsUrl(s))}" target="_blank" rel="noopener noreferrer">${s.coordinates?.kind==='official-link'?'Open MCGM map link ↗':'Get directions ↗'}</a>`:s.coordinates?.kind==='synthetic'?`<div class="map-placeholder"><span class="map-pin">⌖</span><b>Sample location · not a real facility</b><small>Coordinates are synthetic, so directions are turned off.</small></div>`:`<div class="map-placeholder"><span class="map-pin">⌖</span><b>Location pending review</b><small>The map link in the source document couldn’t be read.</small></div>`}</div></div>${bookable(s)?`<aside class="booking-panel"><div class="eyebrow">MAKE A PLAN</div><h2>Choose your arrival</h2><p class="muted">Pick a time window and reserve spaces for your group.</p><button class="primary full" data-book="${escapeHtml(s.id)}">See available times <span>→</span></button><small>No account needed · Takes about a minute</small></aside>`:`<aside class="booking-panel"><div class="eyebrow">PLAN YOUR VISIT</div><h2>No online booking</h2><p class="muted">This is a municipal site. VisarjanOps can’t reserve arrival times here; follow the arrangements at the site.</p><a class="secondary full" href="#help">Need help? →</a></aside>`}</div></main>${footer()}`}
function sourcePanel(s){const p=s.provenance;if(p?.kind!=='official-source')return '';return `<h3>Source</h3><dl class="source-list"><div><dt>Authority</dt><dd>${escapeHtml(p.authority)}</dd></div><div><dt>Document</dt><dd><a href="${escapeHtml(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(p.sourceDocument)}</a></dd></div><div><dt>Festival</dt><dd>${escapeHtml(p.festival)} ${escapeHtml(p.festivalYear)} · past season</dd></div><div><dt>Review</dt><dd>${p.verificationStatus==='VERIFIED'?`Verified ${escapeHtml(p.verifiedAt||'')}`:'Pending operator review'}</dd></div><div><dt>Location</dt><dd>${s.coordinates?`From the map link MCGM published${s.coordinates.method==='viewport-centre'?' (approximate)':''}`:'Not available'}</dd></div><div><dt>Name</dt><dd>${s.nameSource==='ocr'?'Read from the scanned document':s.nameSource==='map-label'?'Taken from the published map link':'Not readable in the scan'}</dd></div></dl>`}
function bookingFlow(s){return `${header()}<main class="page narrow"><a class="back" href="#site/${s.id}">← ${s.name}</a><div class="stepper"><span class="done">1</span><i></i><span class="current">2</span><i></i><span>3</span></div><div class="eyebrow">RESERVE YOUR ARRIVAL</div><h1 class="page-title">A time for togetherness.</h1><p class="page-intro">Choose a time window and tell us a little about your group.</p><div class="form-card"><label class="label">Arrival window</label><div class="slots">${['4:30 – 5:00 PM','5:00 – 5:30 PM','5:30 – 6:00 PM','6:00 – 6:30 PM','6:30 – 7:00 PM'].map((t,i)=>`<button class="slot ${i===3?'selected':''}" data-slot="${t}"><span>${t}</span><small>${i===1?'Filling up':'Spaces available'}</small></button>`).join('')}</div><div class="form-row"><label>Number of people<select id="people">${[1,2,3,4,5,6,7,8].map(n=>`<option ${n===4?'selected':''}>${n}</option>`).join('')}</select></label><label>Visit date<input id="date" type="date" value="2026-11-25"></label></div><div class="form-row"><label>Your name<input id="name" placeholder="Name for the booking" autocomplete="name"></label><label>Email for booking recovery<input id="email" type="email" placeholder="you@example.com" autocomplete="email"></label></div><p class="privacy-note">Your email is only used to recover this booking in the preview app. No account required.</p><button class="primary full" id="confirm">Continue to confirmation <span>→</span></button></div></main>${footer()}`}
function bookingPage(){const b=booking();if(!b)return `${header()}<main class="page narrow empty"><span>▣</span><h1>No booking just yet.</h1><p>Find an immersion site and reserve an arrival window to see your pass here.</p><a class="primary" href="#explore">Explore sites →</a></main>${footer()}`;const site=sites.find(s=>s.id===b.siteId);return `${header()}<main class="page narrow"><div class="eyebrow">VISIT CONFIRMED</div><h1 class="page-title">Your visarjan pass</h1><p class="page-intro">Your booking details are ready whenever you need them.</p><div class="pass-card ${justBooked?'unfold':''}">${justBooked?`<div class="petal-burst" aria-hidden="true">${Array.from({length:12},(_,k)=>`<i style="--a:${k*30}deg;--d:${(k%3)*60}ms"></i>`).join('')}</div>`:''}<div class="pass-top"><span>VISARJAN<span class="brand-light">OPS</span></span><span class="confirmed">✓ CONFIRMED</span></div><div class="pass-visual"><div id="qr-slot" class="qr-slot" role="img" aria-label="Check-in QR code">Loading your QR…</div><div><span class="eyebrow">YOUR BOOKING REFERENCE</span><h2>${b.reference}</h2><p>${b.siteName}</p><p>${b.slot} · ${b.people} people</p></div></div><div class="pass-bottom"><span id="pass-code-line">Show this QR at the site gate. Sample site · not a municipal entry pass.</span><button id="copy-ref">Copy reference</button></div></div><div class="visit-actions"><a href="#visit" class="secondary">Live visit status →</a><a href="#help" class="secondary">Need assistance? →</a></div><div class="map-placeholder smaller"><span>◷</span><b>${site?.statusInfo?.wait?`Sample queue estimate · ${escapeHtml(site.statusInfo.wait)}`:'Queue estimate unavailable'}</b><small>${escapeHtml(site?.statusInfo?.label||'No status source')}</small></div><button id="reset-demo" class="reset-link">Reset sample data</button></main>${footer()}`}
function help(){return `${header()}<main class="page narrow"><div class="eyebrow">HERE WHEN YOU NEED US</div><h1 class="page-title">How can we help?</h1><p class="page-intro">A little support can make the day easier. Choose what you need.</p><div class="help-list">${[['♙','Senior citizen support','Help with walking, seating, or a gentler route.'],['♿','Accessibility assistance','Step-free access and mobility support.'],['♡','First aid','For a minor medical need at the site.'],['✳','General help','Find a volunteer or ask a question.']].map(([i,t,d])=>`<button class="help-card" data-category="${t}"><span class="help-icon">${i}</span><span><b>${t}</b><small>${d}</small></span><span>→</span></button>`).join('')}</div><p class="demo-note">Requests are saved in this preview app. For emergencies, contact your local emergency services.</p></main>${footer()}`}
function opsLogin(){return `${header()}<main class="page narrow auth-page"><div class="auth-emblem" aria-hidden="true">✳</div><div class="eyebrow">TEAM ACCESS</div><h1 class="page-title">Operations sign in</h1><p class="page-intro">For authorised VisarjanOps site and operations staff.</p><form id="ops-login-form" class="form-card auth-card"><label>Staff username<input name="username" autocomplete="username" required placeholder="Enter your team username"></label><label>Password<input name="password" type="password" autocomplete="current-password" required placeholder="Enter your password"></label><p class="auth-status">${opsLoginConfigured?'Sign in using credentials provided by your system administrator.':'Staff sign-in needs to be configured on this server before use.'}</p><button class="primary full" type="submit">Sign in to Operations <span>→</span></button></form><a href="#home" class="back">← Return to public site</a></main>${footer()}`}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function operations(){const viewSites=operationsSites,reporting=viewSites.filter(s=>['live','delayed'].includes(s.statusInfo?.freshness)).length,located=viewSites.filter(hasCoords).length,pendingReview=viewSites.filter(s=>s.provenance?.verificationStatus==='PENDING_REVIEW').length,matches=viewSites.filter(s=>!opsSearch||`${s.name} ${s.area} ${s.address||''}`.toLowerCase().includes(opsSearch.toLowerCase())).sort((a,b)=>(b.statusInfo?.observedAt?1:0)-(a.statusInfo?.observedAt?1:0));const table=matches.slice(0,40).map(s=>`<tr><td><b>${escapeHtml(s.name)}</b><small>${escapeHtml(s.address||s.area)}</small></td><td>${freshnessChip(s)} ${s.statusInfo?.status?badge(s.statusInfo.status):''}<small>${s.statusInfo?.observedAt?`Posted ${escapeHtml(new Date(s.statusInfo.observedAt).toLocaleTimeString())}`:'No update yet'}</small></td><td>${opsFeatures?.flags?.ops_status_updates===false?'<span class="muted small-note">Turned off by the <code>ops_status_updates</code> flag</span>':`<form class="status-form" data-status-site="${escapeHtml(s.id)}"><select name="status" aria-label="Status for ${escapeHtml(s.name)}">${STAFF_STATUSES.map(v=>`<option ${s.statusInfo?.status===v?'selected':''}>${v}</option>`).join('')}</select><input name="waiting" type="number" min="0" max="5000" inputmode="numeric" placeholder="People" aria-label="People waiting" value="${s.statusInfo?.waiting??''}"><input name="waitMinutes" type="number" min="0" max="600" inputmode="numeric" placeholder="Wait (min)" aria-label="Wait in minutes"><button class="primary" type="submit">Post</button></form>`}</td></tr>`).join('');const connected=Boolean(apifyStatus?.connected),latest=apifyStatus?.latestImport,preview=(latest?.items||[]).slice(0,10).map((item,i)=>`<details class="apify-result"><summary>Result ${i+1}</summary><pre>${escapeHtml(JSON.stringify(item,null,2))}</pre></details>`).join('');const connectionText=apifyStatus?(connected?`Connected · Actor ${apifyStatus.actorId}`:`Not connected · Configure APIFY_API_TOKEN${apifyStatus.actorConfigured?'':' and APIFY_ACTOR_ID'} on the server.`):'Checking Apify server configuration…';return `${header()}<main class="page ops-page"><div class="ops-heading"><div><div class="eyebrow">OPERATIONS · SITE STATUS</div><h1 class="page-title">Live site status</h1><p class="page-intro">Post what you see at a site. Visitors see it immediately as Live, then Delayed after 5 minutes and Unavailable after 30.</p></div><div class="ops-actions"><a href="#explore" class="secondary">Public site discovery →</a><button class="secondary" id="ops-logout">Sign out</button></div></div><div class="ops-banner"><span class="demo-dot"></span> SOURCE DATA <span>·</span> MCGM Ganeshotsav 2025 list (past season), auto-extracted and pending review. Status comes only from staff posts here.</div><div class="metric-grid"><article><span>LISTED SITES</span><b>${viewSites.length}</b><small>From the MCGM list</small></article><article><span>ON THE MAP</span><b>${located}</b><small>Location read from MCGM map links</small></article><article><span>REPORTING STATUS</span><b>${reporting}</b><small>Staff update in the last 30 min</small></article><article><span>PENDING REVIEW</span><b>${pendingReview}</b><small>Not yet verified by an operator</small></article></div><section class="apify-panel"><div class="apify-heading"><div><div class="eyebrow">OPTIONAL DATA IMPORT</div><h2>Apify public-source import</h2><p>${connectionText}</p></div><button class="primary" id="apify-run" ${connected&&apifyStatus?.importEnabled!==false?'':'disabled'}>Run configured Actor <span>→</span></button></div><p class="apify-note">Runs only when staff starts it. Results are staged for review and do not change public sites or bookings. Apify usage charges may apply.</p><div id="apify-message" class="apify-message" aria-live="polite"></div>${latest?`<div class="apify-latest"><b>Latest run</b><span>${latest.itemCount} results · ${new Date(latest.importedAt).toLocaleString()} · pending review</span>${preview||'<p>The Actor returned no items.</p>'}</div>`:'<p class="apify-empty">No Apify results have been imported.</p>'}</section>${gatePanel(viewSites)}${opsFeatures?`<section class="flags-panel"><div><div class="eyebrow">FEATURE FLAGS</div><h2>Rollout controls</h2><p>${opsFeatures.flagsmith.mode==='flagsmith'?`Flagsmith connected${opsFeatures.flagsmith.lastLoadedAt?` since ${escapeHtml(new Date(opsFeatures.flagsmith.lastLoadedAt).toLocaleTimeString())}`:' · connecting…'}`:'Flagsmith not configured · using safe defaults'}${opsFeatures.flagsmith.lastError?` · ${escapeHtml(opsFeatures.flagsmith.lastError)}`:''}. Flags never replace staff sign-in.</p></div><ul>${Object.entries(opsFeatures.flags).map(([k,v])=>`<li><code>${escapeHtml(k)}</code><span class="flag-state ${v?'on':'off'}">${v?'On':'Off'}</span></li>`).join('')}<li><code>Sarvam voice</code><span class="flag-state ${opsFeatures.voice.enabled?'on':'off'}">${opsFeatures.voice.enabled?`${opsFeatures.voice.usedToday}/${opsFeatures.voice.dailyLimit} calls today`:'Not configured'}</span></li></ul></section>`:''}<section class="ops-table-wrap"><div class="table-heading"><div><h2>Post a status update</h2><p>Showing ${Math.min(40,matches.length)} of ${matches.length}. Search to find a site.</p></div><label class="ops-search"><span class="sr-only">Search sites</span><input id="ops-search" placeholder="Search site or road" value="${escapeHtml(opsSearch)}"></label></div><div class="table-scroll"><table><thead><tr><th>Site</th><th>Current status</th><th>Update</th></tr></thead><tbody>${table}</tbody></table></div><p class="table-foot">Updates are saved with your session and the time. Only post what you can see on site.</p></section><div class="ops-note"><b>Not yet built</b><span>Operator verification of imported sites, check-in validation and assistance acknowledgement.</span></div></main>${footer()}`}
function render(){const hash=location.hash.slice(1)||'home';view=hash.split('/')[0];if(hash.startsWith('site/')){selected=sites.find(s=>s.id===hash.split('/')[1]);app.innerHTML=selected?siteDetail(selected):home()}else if(hash.startsWith('book/')){selected=sites.find(s=>s.id===hash.split('/')[1]);app.innerHTML=selected?bookingFlow(selected):home()}else if(view==='explore')app.innerHTML=explore();else if(view==='booking'||view==='pass'||view==='visit')app.innerHTML=bookingPage();else if(view==='help')app.innerHTML=help();else if(view==='ops-login')app.innerHTML=opsLogin();else if(view==='operations'){if(!opsAuth){location.hash='ops-login';return;}app.innerHTML=operations()}else if(view==='waste')app.innerHTML=`${header()}<main class="page narrow"><div class="eyebrow">LEAVE A LITTLE GOOD BEHIND</div><h1 class="page-title">A thoughtful goodbye.</h1><p class="page-intro">Simple ways to care for the site and what surrounds it.</p><div class="waste-list"><div><span>01</span><b>Separate offerings</b><p>Place flowers and natural offerings in the marked collection area.</p></div><div><span>02</span><b>Keep the water clean</b><p>Use the designated immersion tank. Avoid plastic, thermocol, and synthetic decorations.</p></div><div><span>03</span><b>Follow site guidance</b><p>Volunteers can point you to the right collection and sorting stations.</p></div></div><div class="demo-note">Waste point locations are illustrative. Follow instructions at your chosen site.</div><a class="secondary" href="#explore">Find a site →</a></main>${footer()}`;else app.innerHTML=home();wire();wireOperationsAuth();wireApify();wireNearby();wireStatusForms();wireGate();wireJourney();revealHeadline();startRiver();if(view==='booking'||view==='pass'||view==='visit')drawQR();}
function wireStatusForms(){const q=document.querySelector('#ops-search');if(q)q.oninput=()=>{opsSearch=q.value;const pos=q.selectionStart;render();const n=document.querySelector('#ops-search');n.focus();n.setSelectionRange(pos,pos)};document.querySelectorAll('[data-status-site]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const btn=f.querySelector('button');btn.disabled=true;const num=v=>v===''?null:Number(v);try{const updated=await api(`/operations/sites/${encodeURIComponent(f.dataset.statusSite)}/status`,{method:'POST',body:JSON.stringify({status:f.elements.status.value,waiting:num(f.elements.waiting.value),waitMinutes:num(f.elements.waitMinutes.value)})});const i=operationsSites.findIndex(x=>x.id===updated.id);if(i>=0)operationsSites[i]=updated;const pub=sites.find(x=>x.id===updated.id);if(pub)pub.statusInfo=updated.statusInfo;toast(`${updated.name}: ${updated.statusInfo.label}.`);render()}catch(err){toast(err.message);btn.disabled=false}})}
async function loadOpsSites(){const r=await fetch('/api/v1/operations/sites');const j=await r.json();if(!r.ok)throw new Error(j.error||'Operations data unavailable.');operationsSites=j.data;opsFeatures=j.features||null;return operationsSites}
// Voice search: the microphone is requested only after a tap; recording stops on a second tap or after 8 seconds.
async function toggleVoice(){if(recorder){recorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){locationMessage='Voice search isn’t supported in this browser. Please type instead.';render();return}let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true})}catch{locationMessage='Microphone permission was declined. You can type a site or area instead.';render();return}const type=['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg'].find(t=>MediaRecorder.isTypeSupported(t))||'';const chunks=[];const rec=new MediaRecorder(stream,type?{mimeType:type}:undefined);recorder=rec;rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};const timer=setTimeout(()=>{if(rec.state==='recording')rec.stop()},8000);rec.onstop=async()=>{clearTimeout(timer);stream.getTracks().forEach(t=>t.stop());const mime=(rec.mimeType||type||'audio/webm').split(';')[0];recorder=null;const recorded=new Blob(chunks,{type:mime});if(recorded.size<4000){locationMessage='I didn’t catch any speech. Check your microphone and try again, or type instead.';render();return}voiceBusy=true;locationMessage='Understanding what you said…';render();try{const r=await fetch('/api/v1/public/voice/search',{method:'POST',headers:{'content-type':mime},body:recorded});const j=await r.json();if(!r.ok)throw new Error(j.error);voiceBusy=false;await applyVoiceResult(j.data)}catch(e){locationMessage=e.message||'Voice search failed. Please type instead.'}finally{voiceBusy=false;render()}};rec.start(250);locationMessage='Listening… say an area or site, for example “immersion ponds near Dadar”. Tap again to stop.';render()}
async function applyVoiceResult({transcript,language,match}){const heard=transcript?`Heard: “${transcript}”. `:'';listLimit=20;if(match.kind==='area'){const a=areaOptions().find(x=>x.area.toLowerCase().startsWith(match.area.toLowerCase()));if(a){here={lat:a.lat,lng:a.lng,kind:'area',siteId:a.id,label:`${a.area} (centre of listed sites)`};locationMessage=`${heard}Showing sites nearest ${a.area}.`}else{search=match.area;locationMessage=`${heard}Showing sites matching ${match.area}.`}}else if(match.kind==='locality'&&Number.isFinite(match.lat)){here={lat:match.lat,lng:match.lng,kind:'area',siteId:null,label:`${match.name} (approximate centre, OpenStreetMap)`};locationMessage=`${heard}Showing sites nearest ${match.name}.`}else if(match.kind==='locality'){search=match.name;locationMessage=`${heard}Showing sites mentioning ${match.name}.`}else if(match.kind==='site'){search=match.name;locationMessage=`${heard}Showing ${match.name}.`}else if(match.kind==='near-me'&&features.nearbyDiscovery){locationMessage=heard+'Finding sites near you…';render();await new Promise(done=>locate(done))}else{locationMessage=`${heard}I couldn’t match that to a listed area or site. Try saying an area name.`;render();await speakResults([],language);return}render();const list=exploreList();await speakResults(match.kind==='site'?list.slice(0,1):list.filter(hasCoords).slice(0,3),language)}
// Distances are only sent for a chosen area; for a device location they could reveal where the visitor is.
async function speakResults(list,language){try{const items=list.map(s=>({id:s.id,meters:here?.kind==='area'&&distanceTo(s)!=null?Math.round(distanceTo(s)*1000):null}));const r=await fetch('/api/v1/public/voice/speak',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({language,items})});const j=await r.json();if(!r.ok)throw new Error(j.error);await new Audio(`data:${j.data.mimeType};base64,${j.data.audio}`).play()}catch(e){toast(e.message||'Could not play the spoken answer.')}}
function gatePanel(viewSites){const bookable=viewSites.filter(s=>s.provenance?.kind==='demo');if(!bookable.length)return '';if(!bookable.some(s=>s.id===gateSite))gateSite=bookable[0].id;const on=opsFeatures?.flags?.ops_status_updates!==false;const rows=bookable.map(s=>{const c=s.crowd||{onSite:0,expected:0,completed:0,groupsOnSite:0,bySlot:{}};const slots=Object.entries(c.bySlot).map(([t,v])=>`${escapeHtml(t)}: ${v.expected} expected · ${v.onSite} in · ${v.completed} done`).join('<br>')||'No bookings yet';return `<tr class="${s.id===gateSite?'gate-row':''}"><td><b>${escapeHtml(s.name)}</b><small>${escapeHtml(s.area)}</small></td><td><b class="crowd-now ${justScanned&&s.id===gateSite?'bump':''}">${c.onSite}</b> people<small>${c.groupsOnSite} ${c.groupsOnSite===1?'group':'groups'}</small></td><td>${c.expected}</td><td>${c.completed}</td><td><small>${slots}</small></td></tr>`}).join('');return `<section class="gate-panel"><div class="gate-head"><div><div class="eyebrow">GATE CHECK-IN · SAMPLE SITES</div><h2>Scan visitor passes</h2><p>First scan checks a group in, the second checks them out. Crowd figures come only from bookings and these scans.</p></div>${on?`<label class="gate-site">Gate at<select id="gate-site">${bookable.map(s=>`<option value="${escapeHtml(s.id)}" ${s.id===gateSite?'selected':''}>${escapeHtml(s.name)} · ${escapeHtml(s.city)}</option>`).join('')}</select></label>`:''}</div>${on?`<div class="gate-actions"><button class="primary" id="scan-start" type="button">${scanning?'■ Stop camera':'📷 Scan QR with camera'}</button><form id="gate-manual" class="gate-manual"><input name="reference" placeholder="VJ-XXXXXXXX" aria-label="Booking reference" autocomplete="off" required><input name="code" placeholder="Check-in code" aria-label="Check-in code" autocomplete="off" required><button class="secondary" type="submit">Check in / out</button></form></div><div class="scan-view" ${scanning?'':'hidden'}><video id="scan-video" playsinline muted></video><p>Point the camera at the visitor's QR code.</p></div><div id="gate-result" class="gate-result" role="status" aria-live="polite">${gateResult}</div>`:'<p class="muted small-note">Gate check-in is turned off by the <code>ops_status_updates</code> flag.</p>'}<div class="table-scroll"><table class="crowd-table"><thead><tr><th>Site</th><th>On site now</th><th>Expected</th><th>Completed</th><th>By slot</th></tr></thead><tbody>${rows}</tbody></table></div></section>`}
function stopScan(){scanning=false;cancelAnimationFrame(scanLoop);scanStream?.getTracks().forEach(t=>t.stop());scanStream=null}
// Camera scanning only after a tap; frames are decoded locally with jsQR and never uploaded.
async function startScan(){if(scanning){stopScan();render();return}if(!navigator.mediaDevices?.getUserMedia){gateResult='<div class="err">Camera isn’t available here (it needs localhost or HTTPS). Type the code instead.</div>';render();return}try{if(!window.jsQR)await new Promise((ok,bad)=>{const sc=document.createElement('script');sc.src='/vendor/jsQR.js';sc.onload=ok;sc.onerror=bad;document.head.append(sc)});scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false})}catch{gateResult='<div class="err">Camera permission was declined or unavailable. Type the code instead.</div>';render();return}scanning=true;gateResult='';render();const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});const tick=async()=>{if(!scanning)return;const video=document.querySelector('#scan-video');if(video&&video.readyState>=2&&video.videoWidth){canvas.width=video.videoWidth;canvas.height=video.videoHeight;ctx.drawImage(video,0,0);const img=ctx.getImageData(0,0,canvas.width,canvas.height);const hit=window.jsQR(img.data,img.width,img.height,{inversionAttempts:'dontInvert'});if(hit?.data){stopScan();await submitScan({payload:hit.data});return}}scanLoop=requestAnimationFrame(tick)};tick()}
async function submitScan(payload){try{const r=await api('/operations/checkin',{method:'POST',body:JSON.stringify({...payload,siteId:gateSite})});gateResult=`<div class="ok ${r.action}"><b>${r.action==='entry'?'✓ Checked in':'✓ Checked out'}</b> · ${escapeHtml(r.reference)} · ${r.people} ${r.people===1?'person':'people'} · ${escapeHtml(r.slot)}<br>${escapeHtml(r.siteName)} now: ~${r.crowd.onSite} on site, ${r.crowd.expected} still expected</div>`;justScanned=true;await loadOpsSites()}catch(e){gateResult=`<div class="err">${escapeHtml(e.message)}</div>`}render()}
function wireGate(){justLocated=justBooked=justScanned=false;const video=document.querySelector('#scan-video');if(scanning&&!video)stopScan();if(scanning&&video&&scanStream&&video.srcObject!==scanStream){video.srcObject=scanStream;video.play().catch(()=>{})}const site=document.querySelector('#gate-site');if(site)site.onchange=()=>{gateSite=site.value;gateResult='';render()};const start=document.querySelector('#scan-start');if(start)start.onclick=startScan;const form=document.querySelector('#gate-manual');if(form)form.onsubmit=e=>{e.preventDefault();submitScan({reference:form.elements.reference.value,code:form.elements.code.value})}}
// Home hero: a 3D coverflow of the visitor's journey. User-controllable, pauses on hover/focus, still under reduced motion.
const JOURNEY=[
 {title:'Find a pond near you',text:'Share your location once or pick an area. Official MCGM ponds appear on the map, nearest first.',tone:'river',icon:'<path d="M24 42s-13-12-13-22a13 13 0 0 1 26 0c0 10-13 22-13 22z"/><circle cx="24" cy="20" r="5"/>'},
 {title:'Ask in your language',text:'Say “Dadar madhe visarjan talav” and hear the nearest sites in Marathi, Hindi, Kannada or English.',tone:'dusk',icon:'<rect x="18" y="6" width="12" height="22" rx="6"/><path d="M12 22a12 12 0 0 0 24 0M24 34v8M17 42h14"/>'},
 {title:'Book a time, get a QR',text:'Reserve an arrival window at a demo site and keep a scannable pass on your phone.',tone:'marigold',icon:'<rect x="8" y="8" width="12" height="12" rx="1.5"/><rect x="28" y="8" width="12" height="12" rx="1.5"/><rect x="8" y="28" width="12" height="12" rx="1.5"/><path d="M28 28h5v5h-5zM36 36h4v4M28 40h4M40 28v4"/>'},
 {title:'Check in at the gate',text:'Staff scan you in and out, so everyone sees how crowded the site is right now.',tone:'leaf',icon:'<path d="M8 40V18l16-10 16 10v22"/><path d="M17 27l5 5 9-10"/>'}
];
let journeyIndex=0,journeyTimer=0,journeyPaused=false;
function journeyCarousel(){return `<div class="hero-visual journey" role="region" aria-roledescription="carousel" aria-label="How VisarjanOps helps on visarjan day"><div class="journey-stage" id="journey-stage">${JOURNEY.map((j,i)=>`<article class="journey-card tone-${j.tone}" data-slide="${i}" aria-roledescription="slide" aria-label="Step ${i+1} of ${JOURNEY.length}"><span class="journey-step">Step ${i+1}</span><svg class="journey-icon" viewBox="0 0 48 48" aria-hidden="true">${j.icon}</svg><h3>${j.title}</h3><p>${j.text}</p></article>`).join('')}</div><div class="journey-controls"><button class="journey-nav" type="button" data-journey="-1" aria-label="Previous step">‹</button><div class="journey-dots">${JOURNEY.map((j,i)=>`<button type="button" class="journey-dot" data-journey-go="${i}" aria-label="Show step ${i+1}: ${j.title}"></button>`).join('')}</div><button class="journey-nav" type="button" data-journey="1" aria-label="Next step">›</button></div></div>`}
function setJourney(n){const cards=[...document.querySelectorAll('.journey-card')];if(!cards.length)return;const total=cards.length;journeyIndex=(n%total+total)%total;cards.forEach((c,i)=>{let o=(i-journeyIndex+total)%total;if(o>total/2)o-=total;const a=Math.abs(o);c.style.transform=`translateX(${o*64}%) translateZ(${-a*170}px) rotateY(${o*-40}deg)`;c.style.opacity=a>1?'0':a?'.5':'1';c.style.zIndex=String(10-a);c.classList.toggle('is-active',o===0);c.setAttribute('aria-hidden',String(o!==0))});document.querySelectorAll('.journey-dot').forEach((d,i)=>d.setAttribute('aria-current',String(i===journeyIndex)))}
function wireJourney(){clearInterval(journeyTimer);const stage=document.querySelector('#journey-stage');if(!stage)return;setJourney(journeyIndex);document.querySelectorAll('[data-journey]').forEach(b=>b.onclick=()=>setJourney(journeyIndex+Number(b.dataset.journey)));document.querySelectorAll('[data-journey-go]').forEach(b=>b.onclick=()=>setJourney(Number(b.dataset.journeyGo)));document.querySelectorAll('.journey-card').forEach(c=>c.onclick=()=>setJourney(Number(c.dataset.slide)));const root=stage.closest('.journey');root.onmouseenter=root.onfocusin=()=>journeyPaused=true;root.onmouseleave=root.onfocusout=()=>journeyPaused=false;let x0=null;stage.ontouchstart=e=>x0=e.touches[0].clientX;stage.ontouchend=e=>{if(x0==null)return;const dx=e.changedTouches[0].clientX-x0;if(Math.abs(dx)>40)setJourney(journeyIndex+(dx<0?1:-1));x0=null};if(!matchMedia('(prefers-reduced-motion: reduce)').matches)journeyTimer=setInterval(()=>{if(!journeyPaused&&!document.hidden)setJourney(journeyIndex+1)},4200)}
// Home hero: a WebGL river (three.js) with drifting lantern lights. Loaded only on capable desktops on the home page;
// skipped for reduced motion, data saver or small screens, which keep the static gradient.
let THREE=null,river=null;
const riverAllowed=()=>innerWidth>=900&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!navigator.connection?.saveData;
function stopRiver(){if(!river)return;cancelAnimationFrame(river.raf);removeEventListener('resize',river.onResize);removeEventListener('pointermove',river.onMove);river.renderer.dispose();river.geometries.forEach(g=>g.dispose());river=null}
async function startRiver(){const canvas=document.querySelector('.river-canvas');if(!canvas){stopRiver();return}if(river?.canvas===canvas)return;stopRiver();if(!riverAllowed())return;try{THREE||=await import('/vendor/three.module.js')}catch{return}if(!canvas.isConnected)return;let renderer;try{renderer=new THREE.WebGLRenderer({canvas,antialias:false,alpha:false,powerPreference:'low-power'})}catch{return}
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));const scene=new THREE.Scene();scene.background=new THREE.Color('#0B2330');scene.fog=new THREE.Fog('#0B2330',9,30);
 const camera=new THREE.PerspectiveCamera(52,1,.1,100);camera.position.set(0,2.4,8.5);camera.lookAt(0,0,-4);
 const water=new THREE.PlaneGeometry(48,30,180,110);water.rotateX(-Math.PI/2);
 const waterMat=new THREE.ShaderMaterial({uniforms:{uTime:{value:0}},vertexShader:`uniform float uTime;varying float vH;varying vec3 vPos;void main(){vec3 p=position;float h=sin(p.x*.55+uTime*.7)*.16+sin(p.z*.8-uTime*.9)*.12+sin((p.x+p.z)*1.6+uTime*1.3)*.05;p.y+=h;vH=h;vPos=p;gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.);}`,fragmentShader:`varying float vH;varying vec3 vPos;void main(){vec3 deep=vec3(.043,.137,.188);vec3 teal=vec3(.106,.498,.525);vec3 c=mix(deep,teal,smoothstep(-.25,.32,vH));float lines=smoothstep(.985,1.,sin(vPos.z*6.+vH*18.));c+=lines*vec3(.95,.66,.23)*.18;float d=length(vPos.xz-vec2(0.,-2.));c+=vec3(.95,.66,.23)*.10*exp(-d*.18);gl_FragColor=vec4(c,1.);}`});
 scene.add(new THREE.Mesh(water,waterMat));
 const count=320,pos=new Float32Array(count*3),seed=new Float32Array(count);for(let k=0;k<count;k++){pos[k*3]=(Math.random()-.5)*26;pos[k*3+1]=Math.random()*6;pos[k*3+2]=-Math.random()*22+4;seed[k]=Math.random()}
 const lights=new THREE.BufferGeometry();lights.setAttribute('position',new THREE.BufferAttribute(pos,3));lights.setAttribute('seed',new THREE.BufferAttribute(seed,1));
 const lightMat=new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,uniforms:{uTime:{value:0}},vertexShader:`uniform float uTime;attribute float seed;varying float vA;void main(){vec3 p=position;p.y=mod(p.y+uTime*(.12+seed*.18),6.);p.x+=sin(uTime*.3+seed*20.)*.35;vec4 mv=modelViewMatrix*vec4(p,1.);gl_PointSize=(7.+seed*10.)*(6./-mv.z);vA=(.35+seed*.65)*smoothstep(0.,.8,p.y)*smoothstep(6.,4.5,p.y);gl_Position=projectionMatrix*mv;}`,fragmentShader:`varying float vA;void main(){float d=length(gl_PointCoord-.5);float a=smoothstep(.5,0.,d);gl_FragColor=vec4(vec3(1.,.72,.32)*a,a*vA);}`});
 scene.add(new THREE.Points(lights,lightMat));
 const mouse={x:0,y:0};const onMove=e=>{mouse.x=e.clientX/innerWidth-.5;mouse.y=e.clientY/innerHeight-.5};const onResize=()=>{const r=canvas.parentElement.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/Math.max(r.height,1);camera.updateProjectionMatrix()};addEventListener('pointermove',onMove,{passive:true});addEventListener('resize',onResize);onResize();
 const clock=new THREE.Clock();river={canvas,renderer,onMove,onResize,geometries:[water,lights],raf:0};
 const frame=()=>{if(!canvas.isConnected){stopRiver();return}river.raf=requestAnimationFrame(frame);if(document.hidden)return;const t=clock.getElapsedTime();waterMat.uniforms.uTime.value=t;lightMat.uniforms.uTime.value=t;camera.position.x+=(mouse.x*1.2-camera.position.x)*.04;camera.position.y+=((2.4-mouse.y*.6)-camera.position.y)*.04;camera.lookAt(0,0,-4);renderer.render(scene,camera)};frame();canvas.classList.add('is-live')}
// Headline rises in word by word once per visit to the home page.
function revealHeadline(){const h=document.querySelector('.river-hero h1');if(!h||h.dataset.split)return;h.dataset.split='1';let k=0;const walk=n=>{for(const c of [...n.childNodes]){if(c.nodeType===3){const f=document.createDocumentFragment();c.textContent.split(/(\s+)/).forEach(w=>{if(!w)return;if(/^\s+$/.test(w)){f.append(w);return}const sp=document.createElement('span');sp.className='word';sp.style.setProperty('--w',k++);sp.textContent=w;f.append(sp)});c.replaceWith(f)}else if(c.nodeType===1&&c.tagName!=='BR')walk(c)}};walk(h);h.classList.add('words-in')}
function setLocation(next,message){here=next;locationMessage=message;justLocated=Boolean(next);render();}
// One-time lookup only after the visitor taps the button; no watchPosition, nothing stored or sent.
function locate(onDone){if(!('geolocation' in navigator)){locationMessage='This browser can’t share location. Choose an area instead.';render();onDone?.();return}if(!window.isSecureContext){locationMessage='Location sharing needs a secure (HTTPS) connection. Choose an area instead.';render();onDone?.();return}locating=true;locationMessage='Waiting for your browser’s permission prompt…';render();navigator.geolocation.getCurrentPosition(p=>{locating=false;setLocation({lat:p.coords.latitude,lng:p.coords.longitude,kind:'device',label:'your location'},`Sorted from your location (accurate to about ${Math.round(p.coords.accuracy)} m).`);onDone?.()},e=>{locating=false;here=null;const messages={1:'Location permission was declined. That’s fine: choose an area instead, or allow location in your browser settings and try again.',2:'Your location isn’t available right now. Choose an area instead.',3:'Finding your location took too long. Try again or choose an area instead.'};locationMessage=messages[e.code]||'We couldn’t get your location. Choose an area instead.';render();onDone?.()},{enableHighAccuracy:false,timeout:10000,maximumAge:300000});}
function wireNearby(){const use=document.querySelector('#use-location');if(use)use.onclick=locate;const voice=document.querySelector('#voice-search');if(voice)voice.onclick=toggleVoice;const area=document.querySelector('#area');if(area)area.onchange=()=>{const a=areaOptions().find(x=>x.id===area.value);listLimit=20;if(!a){setLocation(null,'');return}setLocation({lat:a.lat,lng:a.lng,kind:'area',siteId:a.id,label:`${a.area} (centre of listed sites)`},`Showing sites nearest ${a.area}. Use “Use my location” for a closer match.`)};const clear=document.querySelector('#clear-location');if(clear)clear.onclick=()=>{listLimit=20;setLocation(null,'Location cleared.')};document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>{city=b.dataset.city;listLimit=20;render()});const toggle=document.querySelector('#map-toggle');if(toggle)toggle.onclick=()=>{mapOpen=!mapOpen;render()};const more=document.querySelector('#list-more');if(more)more.onclick=()=>{listLimit+=20;render()};document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>focusSite(b.dataset.focus));if(document.querySelector('#site-map-slot'))syncMap(exploreList());}
const popupHtml=s=>{const km=distanceTo(s),dir=directionsUrl(s),i=s.statusInfo;return `<div class="map-popup"><b>${escapeHtml(s.name)}</b><small>${escapeHtml(s.address||s.area)}</small><span class="popup-status">${i?.status?`${escapeHtml(i.status)} · ${escapeHtml(i.label)}`:'No status reported yet'}</span>${s.crowd?`<span class="popup-status">${crowdText(s)} (from check-ins)</span>`:''}${km!=null?`<span>${distanceText(km)}</span>`:''}<span class="popup-actions"><a href="#site/${encodeURIComponent(s.id)}">Details →</a>${dir?`<a href="${escapeHtml(dir)}" target="_blank" rel="noopener noreferrer">Directions ↗</a>`:''}</span></div>`};
function highlightRow(id){document.querySelectorAll('.site-row.active').forEach(r=>r.classList.remove('active'));const row=document.querySelector(`.site-row[data-focus="${CSS.escape(id)}"]`);if(row){row.classList.add('active');row.scrollIntoView({block:'nearest',behavior:'smooth'})}}
function focusSite(id){const marker=markers.get(id);if(!marker||!mapInstance||!mapOpen){location.hash=`site/${id}`;return}for(const [key,m] of markers)if(key!==id&&m.getPopup()?.isOpen())m.togglePopup();mapInstance.flyTo({center:marker.getLngLat(),zoom:Math.max(mapInstance.getZoom(),14.5),duration:600});if(!marker.getPopup().isOpen())marker.togglePopup();highlightRow(id);if(window.innerWidth<900)document.querySelector('#site-map-slot')?.scrollIntoView({behavior:'smooth',block:'start'})}
async function ensureMap(){if(mapInstance)return mapInstance;if(!mapLib){if(!document.querySelector('link[data-maplibre]')){const l=document.createElement('link');l.rel='stylesheet';l.href='/vendor/maplibre-gl.css';l.dataset.maplibre='true';document.head.append(l)}mapLib=await import('/vendor/maplibre-gl.mjs')}if(mapInstance)return mapInstance;mapEl=document.createElement('div');mapEl.className='site-map';mapEl.setAttribute('role','region');mapEl.setAttribute('aria-label','Map of immersion sites');document.querySelector('#site-map-slot')?.append(mapEl);mapInstance=new mapLib.Map({container:mapEl,style:'https://tiles.openfreemap.org/styles/liberty',center:[72.8777,19.076],zoom:10.3,attributionControl:{compact:true}});mapInstance.addControl(new mapLib.NavigationControl({showCompass:false}),'top-right');mapInstance.on('error',()=>{const n=document.querySelector('.map-note');if(n&&!n.dataset.warned){n.dataset.warned='1';n.prepend('Some map tiles could not load; the list still has every site. ')}});return mapInstance}
// The map element survives re-renders: it is moved into the new slot instead of being rebuilt on every keystroke.
let justLocatedMap=false;
async function syncMap(list){if(justLocated)justLocatedMap=true;const slot=document.querySelector('#site-map-slot');if(!slot)return;try{const map=await ensureMap();if(!slot.isConnected)return;if(mapEl.parentNode!==slot)slot.append(mapEl);map.resize();for(const m of markers.values())m.remove();markers.clear();const located=list.filter(hasCoords);for(const s of located){const el=document.createElement('button');el.type='button';el.className=`map-marker pin-${s.statusInfo?.freshness||'unavailable'}`;el.setAttribute('aria-label',s.name);el.addEventListener('click',()=>highlightRow(s.id));markers.set(s.id,new mapLib.Marker({element:el}).setLngLat([s.coordinates.lng,s.coordinates.lat]).setPopup(new mapLib.Popup({offset:14,maxWidth:'270px'}).setHTML(popupHtml(s))).addTo(map))}if(here){const me=document.createElement('div');me.className=(here.kind==='device'?'map-me':'map-area')+(justLocatedMap?' located':'');justLocatedMap=false;me.setAttribute('aria-label',here.kind==='device'?'Your location':'Selected area');markers.set('__here',new mapLib.Marker({element:me}).setLngLat([here.lng,here.lat]).addTo(map))}const key=[here?.lat,here?.lng,city,filter,search].join('|');if(key!==mapFitKey){mapFitKey=key;const focus=here?located.slice(0,5):located;const pts=[...focus.map(s=>[s.coordinates.lng,s.coordinates.lat]),...(here?[[here.lng,here.lat]]:[])];if(pts.length===1)map.jumpTo({center:pts[0],zoom:14});else if(pts.length>1){const b=new mapLib.LngLatBounds(pts[0],pts[0]);pts.forEach(p=>b.extend(p));map.fitBounds(b,{padding:56,maxZoom:14.5,duration:here?700:0})}}}catch{slot.innerHTML='<p class="map-fallback">The map couldn’t load. The list has every site.</p>'}}
function wire(){document.querySelectorAll('[data-site]').forEach(b=>b.onclick=()=>location.hash=`site/${b.dataset.site}`);document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>location.hash=`book/${b.dataset.book}`);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;listLimit=20;render()});const q=document.querySelector('#search');if(q)q.oninput=()=>{search=q.value;listLimit=20;const pos=q.selectionStart;render();document.querySelector('#search').focus();document.querySelector('#search').setSelectionRange(pos,pos)};document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-slot]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')});const confirm=document.querySelector('#confirm');if(confirm)confirm.onclick=async()=>{const name=document.querySelector('#name').value.trim(),email=document.querySelector('#email').value.trim();if(!name||!/^\S+@\S+\.\S+$/.test(email)){toast('Add your name and a valid email to continue.');return}confirm.disabled=true;confirm.textContent='Saving your booking…';try{const b=await api('/bookings',{method:'POST',body:JSON.stringify({siteId:selected.id,slot:document.querySelector('.slot.selected')?.dataset.slot||'6:00 – 6:30 PM',people:Number(document.querySelector('#people').value),name,email})});saveBooking(b);justBooked=true;location.hash='booking';}catch(e){toast(e.message);confirm.disabled=false;confirm.innerHTML='Continue to confirmation <span>→</span>'}};document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>requestHelp(b.dataset.category));const copy=document.querySelector('#copy-ref');if(copy)copy.onclick=()=>{navigator.clipboard?.writeText(booking().reference);toast('Booking reference copied.')};const reset=document.querySelector('#reset-demo');if(reset)reset.onclick=async()=>{await api('/demo/reset',{method:'POST'});localStorage.removeItem('visarjanops-booking');toast('Sample data reset.');location.hash='home';};}
function wireOperationsAuth(){const form=document.querySelector('#ops-login-form');if(form)form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('button[type="submit"]'),username=form.elements.username.value.trim(),password=form.elements.password.value;submit.disabled=true;submit.textContent='Signing in…';try{opsAuth=await api('/operations/auth/login',{method:'POST',body:JSON.stringify({username,password})});await loadOpsSites();apifyStatus=await api('/operations/apify/status').catch(()=>null);form.reset();location.hash='operations';}catch(error){opsAuth=null;form.querySelector('.auth-status').textContent=error.message;form.querySelector('.auth-status').setAttribute('role','alert');submit.disabled=false;submit.innerHTML='Sign in to Operations <span>→</span>'}};const logout=document.querySelector('#ops-logout');if(logout)logout.onclick=async()=>{try{await api('/operations/auth/logout',{method:'POST'})}finally{opsAuth=null;operationsSites=[];apifyStatus=null;location.hash='home';toast('Signed out of Operations.')}}}
function wireApify(){const button=document.querySelector('#apify-run');if(!button)return;button.onclick=async()=>{button.disabled=true;button.textContent='Running Actor…';const message=document.querySelector('#apify-message');message.textContent='Waiting for Apify. This can take up to five minutes.';try{const result=await api('/operations/apify/run',{method:'POST'});apifyStatus={...apifyStatus,latestImport:result};render();toast(`${result.itemCount} Apify results staged for review.`)}catch(error){message.textContent=error.message;button.disabled=!apifyStatus?.connected;button.innerHTML='Run configured Actor <span>→</span>'}}}
async function refreshOperationsSession(){if(!opsAuth)return;try{const status=await api('/operations/auth/session');if(!status.authenticated)throw new Error('Session ended');}catch{opsAuth=null;operationsSites=[];if(location.hash==='#operations'){location.hash='ops-login';toast('Your operations session has ended. Please sign in again.');}}}
async function requestHelp(category){const b=booking();if(!b){toast('Make a booking first so the site team knows where to find you.');return}try{const r=await api('/assistance-requests',{method:'POST',body:JSON.stringify({bookingReference:b.reference,category})});toast(`Request ${r.reference} received. Status: ${r.status}.`)}catch(e){toast(e.message)}}
async function drawQR(){const slot=document.querySelector('#qr-slot'),b=booking();if(!slot||!b)return;if(!b.recoveryKey){slot.textContent='Open this pass on the device you booked from to see its QR.';return}try{const p=await api(`/bookings/${encodeURIComponent(b.reference)}/pass?key=${encodeURIComponent(b.recoveryKey)}`);if(!slot.isConnected)return;slot.innerHTML=p.qrSvg;const line=document.querySelector('#pass-code-line');if(line)line.innerHTML=`Check-in code <b>${escapeHtml(p.passCode)}</b> · ${{booked:'Not checked in yet','on-site':`Checked in ${new Date(p.checkedInAt).toLocaleTimeString()}`,exited:'Visit completed'}[p.visitStatus]||''}`;const badge=document.querySelector('.confirmed');if(badge)badge.textContent={booked:'✓ CONFIRMED','on-site':'● CHECKED IN',exited:'✓ COMPLETED'}[p.visitStatus]||badge.textContent}catch(e){slot.textContent='Could not load your QR. '+e.message}}
window.addEventListener('hashchange',render);const initial=await api('/sites').catch(()=>null);if(!initial){app.innerHTML='<main class="offline"><h1>We could not reach the VisarjanOps service.</h1><p>Start the app with <code>npm run dev</code> and refresh this page.</p></main>';}else{sites=initial;features=await api('/features').catch(()=>features);mapOpen=features.mapView;const session=await api('/operations/auth/session').catch(()=>null);opsLoginConfigured=Boolean(session?.loginConfigured);if(session?.authenticated){opsAuth=session;await loadOpsSites().catch(()=>{opsAuth=null;operationsSites=[]});if(opsAuth)apifyStatus=await api('/operations/apify/status').catch(()=>null)}render();const events=new EventSource('/api/v1/public/live');events.onmessage=e=>{const live=JSON.parse(e.data);for(const x of live.sites){const s=sites.find(y=>y.id===x.id);if(s&&x.statusInfo)s.statusInfo=x.statusInfo;if(s&&'crowd' in x)s.crowd=x.crowd}};setInterval(refreshOperationsSession,60000);}
